const fs = require('fs');
const path = require('path');
const dir = __dirname;

// All lodash subpath functions that recharts uses
const fns = {
  every: 'lodash-every.js',
  find: 'lodash-find.js',
  first: 'lodash-first.js',
  flatMap: 'lodash-flatmap.js',
  get: 'lodash-get.js',
  isBoolean: 'lodash-isboolean.js',
  isEqual: 'lodash-isequal.js',
  isFunction: 'lodash-isfunction.js',
  isNaN: 'lodash-isnan.js',
  isNil: 'lodash-isnil.js',
  isNumber: 'lodash-isnumber.js',
  isObject: 'lodash-isobject.js',
  isPlainObject: 'lodash-isplainobject.js',
  isString: 'lodash-isstring.js',
  last: 'lodash-last.js',
  mapValues: 'lodash-mapvalues.js',
  max: 'lodash-max.js',
  maxBy: 'lodash-maxby.js',
  memoize: 'lodash-memoize.js',
  min: 'lodash-min.js',
  minBy: 'lodash-minby.js',
  omit: 'lodash-omit.js',
  range: 'lodash-range.js',
  some: 'lodash-some.js',
  sortBy: 'lodash-sortby.js',
  sumBy: 'lodash-sumby.js',
  throttle: 'lodash-throttle.js',
  uniqBy: 'lodash-uniqby.js',
  upperFirst: 'lodash-upperfirst.js',
};

// Absolute path to lodash bundle (works regardless of Vite resolver)
const lodashBundle = path.resolve(dir, '../../../node_modules/lodash/lodash.js').replace(/\\/g, '/');

for (const [fn, filename] of Object.entries(fns)) {
  // Use Vite-compatible ESM that imports lodash by package name
  // 'lodash' resolves to the lodash bundle since it's in node_modules
  const content = [
    "// ESM shim for lodash/" + fn + " — proxies through the main lodash bundle.",
    "// This file is generated by gen-shims.cjs",
    "import _l from 'lodash';",
    "const _fn = _l." + fn + ";",
    "export default _fn;",
    "export { _fn as " + fn + " };",
    "",
  ].join('\n');
  fs.writeFileSync(path.join(dir, filename), content, 'utf8');
  process.stdout.write('written: ' + filename + '\n');
}
console.log('all done');
